from abc import ABC, abstractmethod

class Druckbar(ABC):
    @abstractmethod
    def drucken(self) -> str: ...

class Versendbar(ABC):
    @abstractmethod
    def versenden(self) -> str: ...

class Rechnung(Druckbar, Versendbar):
    def drucken(self) -> str:
        return "R druckt"

    def versenden(self) -> str:
        return "R sendet"

class Lieferschein(Druckbar):
    def drucken(self) -> str:
        return "L druckt"

for d in [Rechnung(), Lieferschein()]:
    if isinstance(d, Versendbar):
        print(d.versenden())

from abc import ABC, abstractmethod
from decimal import Decimal

class Produkt(ABC):
    def __init__(self, preis: Decimal) -> None:
        self.preis = preis

    @abstractmethod
    def mwst_satz(self) -> Decimal: ...

    def bruttopreis(self) -> Decimal:
        return (self.preis * (1 + self.mwst_satz())).quantize(Decimal("0.01"))

class Lebensmittel(Produkt):
    def mwst_satz(self) -> Decimal:
        return Decimal("0.07")

class Zubehoer(Produkt):
    def mwst_satz(self) -> Decimal:
        return Decimal("0.19")

kaffee = Lebensmittel(Decimal("12.99"))
presse = Zubehoer(Decimal("20.90"))
print(kaffee.bruttopreis(), presse.bruttopreis())

def finden(nummern: list[int], gesucht: int) -> int | None:
    for nummer in nummern:
        if nummer == gesucht:
            return nummer
        else:
            return None
    return None

print(finden([101, 102, 203], 203))

